-- minmax
SELECT MIN("loan_id"), MAX("loan_id"), SUM(CASE WHEN "loan_id" IS NULL THEN 1 ELSE 0 END), COUNT(*) FROM analytics.loans WHERE (status <> 'TEST')

-- count_sampled
SELECT COUNT(*) FROM analytics.loans WHERE (status <> 'TEST') AND ((((STRTOL(SUBSTRING(MD5(COALESCE('V' || CAST("loan_id" AS VARCHAR(65535)), 'N')), 18), 16)) / (1048576))) % (10000)) < 500

-- duplicate_keys
SELECT COUNT(*) FROM (SELECT "loan_id" FROM analytics.loans WHERE (status <> 'TEST') GROUP BY "loan_id" HAVING COUNT(*) > 1) d

-- range_checksum_level0
SELECT ((rk - (1)) / (16384)) AS b, COUNT(*) AS n, SUM(CAST(h AS DECIMAL(38, 0))) AS s FROM (SELECT CAST("loan_id" AS BIGINT) AS rk, STRTOL(SUBSTRING(MD5(COALESCE('V' || CAST("loan_id" AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || CAST(CAST("amount" AS DECIMAL(38, 2)) AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || CAST(CAST(CAST("rate" AS DOUBLE PRECISION) AS DECIMAL(38, 6)) AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || NULLIF(RTRIM(CAST("status" AS VARCHAR(65535))), ''), 'N') || '|' || COALESCE('V' || LOWER(CAST("ref" AS VARCHAR(65535))), 'N') || '|' || COALESCE('V' || CASE WHEN "active" THEN 'true' WHEN NOT "active" THEN 'false' END, 'N') || '|' || COALESCE('V' || CASE WHEN "flag" THEN '1' WHEN NOT "flag" THEN '0' END, 'N') || '|' || COALESCE('V' || TO_CHAR("opened", 'YYYY-MM-DD'), 'N') || '|' || COALESCE('V' || TO_CHAR(CAST("booked" AS TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS.US'), 'N') || '|' || COALESCE('V' || TO_CHAR(("created_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 'N') || '|' || COALESCE('V' || SUBSTR(TO_CHAR((("updated_at" AT TIME ZONE 'Asia/Singapore') AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 1, 23), 'N')), 18), 16) AS h FROM analytics.loans WHERE (status <> 'TEST') AND ("loan_id" >= 1 AND "loan_id" <= 1000000)) t GROUP BY 1

-- range_checksum_level1
SELECT ((rk - (1)) / (512)) AS b, COUNT(*) AS n, SUM(CAST(h AS DECIMAL(38, 0))) AS s FROM (SELECT CAST("loan_id" AS BIGINT) AS rk, STRTOL(SUBSTRING(MD5(COALESCE('V' || CAST("loan_id" AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || CAST(CAST("amount" AS DECIMAL(38, 2)) AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || CAST(CAST(CAST("rate" AS DOUBLE PRECISION) AS DECIMAL(38, 6)) AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || NULLIF(RTRIM(CAST("status" AS VARCHAR(65535))), ''), 'N') || '|' || COALESCE('V' || LOWER(CAST("ref" AS VARCHAR(65535))), 'N') || '|' || COALESCE('V' || CASE WHEN "active" THEN 'true' WHEN NOT "active" THEN 'false' END, 'N') || '|' || COALESCE('V' || CASE WHEN "flag" THEN '1' WHEN NOT "flag" THEN '0' END, 'N') || '|' || COALESCE('V' || TO_CHAR("opened", 'YYYY-MM-DD'), 'N') || '|' || COALESCE('V' || TO_CHAR(CAST("booked" AS TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS.US'), 'N') || '|' || COALESCE('V' || TO_CHAR(("created_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 'N') || '|' || COALESCE('V' || SUBSTR(TO_CHAR((("updated_at" AT TIME ZONE 'Asia/Singapore') AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 1, 23), 'N')), 18), 16) AS h FROM analytics.loans WHERE (status <> 'TEST') AND (("loan_id" >= 1 AND "loan_id" < 32769) OR ("loan_id" >= 114689 AND "loan_id" < 131073))) t GROUP BY 1

-- range_fetch
SELECT CAST("loan_id" AS VARCHAR(65535)) AS c0, CAST(CAST("amount" AS DECIMAL(38, 2)) AS VARCHAR(65535)) AS c1, CAST(CAST(CAST("rate" AS DOUBLE PRECISION) AS DECIMAL(38, 6)) AS VARCHAR(65535)) AS c2, NULLIF(RTRIM(CAST("status" AS VARCHAR(65535))), '') AS c3, LOWER(CAST("ref" AS VARCHAR(65535))) AS c4, CASE WHEN "active" THEN 'true' WHEN NOT "active" THEN 'false' END AS c5, CASE WHEN "flag" THEN '1' WHEN NOT "flag" THEN '0' END AS c6, TO_CHAR("opened", 'YYYY-MM-DD') AS c7, TO_CHAR(CAST("booked" AS TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS.US') AS c8, TO_CHAR(("created_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US') AS c9, SUBSTR(TO_CHAR((("updated_at" AT TIME ZONE 'Asia/Singapore') AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 1, 23) AS c10 FROM analytics.loans WHERE (status <> 'TEST') AND (("loan_id" >= 161 AND "loan_id" < 193) OR ("loan_id" >= 641 AND "loan_id" < 657))

-- hash_checksum_level0
SELECT ((kh) % (64)) AS b, COUNT(*) AS n, SUM(CAST(h AS DECIMAL(38, 0))) AS s FROM (SELECT STRTOL(SUBSTRING(MD5(COALESCE('V' || CAST("loan_id" AS VARCHAR(65535)), 'N')), 18), 16) AS kh, STRTOL(SUBSTRING(MD5(COALESCE('V' || CAST("loan_id" AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || CAST(CAST("amount" AS DECIMAL(38, 2)) AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || CAST(CAST(CAST("rate" AS DOUBLE PRECISION) AS DECIMAL(38, 6)) AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || NULLIF(RTRIM(CAST("status" AS VARCHAR(65535))), ''), 'N') || '|' || COALESCE('V' || LOWER(CAST("ref" AS VARCHAR(65535))), 'N') || '|' || COALESCE('V' || CASE WHEN "active" THEN 'true' WHEN NOT "active" THEN 'false' END, 'N') || '|' || COALESCE('V' || CASE WHEN "flag" THEN '1' WHEN NOT "flag" THEN '0' END, 'N') || '|' || COALESCE('V' || TO_CHAR("opened", 'YYYY-MM-DD'), 'N') || '|' || COALESCE('V' || TO_CHAR(CAST("booked" AS TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS.US'), 'N') || '|' || COALESCE('V' || TO_CHAR(("created_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 'N') || '|' || COALESCE('V' || SUBSTR(TO_CHAR((("updated_at" AT TIME ZONE 'Asia/Singapore') AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 1, 23), 'N')), 18), 16) AS h FROM analytics.loans WHERE (status <> 'TEST')) t GROUP BY 1

-- hash_checksum_level1_sampled
SELECT ((kh) % (2048)) AS b, COUNT(*) AS n, SUM(CAST(h AS DECIMAL(38, 0))) AS s FROM (SELECT STRTOL(SUBSTRING(MD5(COALESCE('V' || CAST("loan_id" AS VARCHAR(65535)), 'N')), 18), 16) AS kh, STRTOL(SUBSTRING(MD5(COALESCE('V' || CAST("loan_id" AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || CAST(CAST("amount" AS DECIMAL(38, 2)) AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || CAST(CAST(CAST("rate" AS DOUBLE PRECISION) AS DECIMAL(38, 6)) AS VARCHAR(65535)), 'N') || '|' || COALESCE('V' || NULLIF(RTRIM(CAST("status" AS VARCHAR(65535))), ''), 'N') || '|' || COALESCE('V' || LOWER(CAST("ref" AS VARCHAR(65535))), 'N') || '|' || COALESCE('V' || CASE WHEN "active" THEN 'true' WHEN NOT "active" THEN 'false' END, 'N') || '|' || COALESCE('V' || CASE WHEN "flag" THEN '1' WHEN NOT "flag" THEN '0' END, 'N') || '|' || COALESCE('V' || TO_CHAR("opened", 'YYYY-MM-DD'), 'N') || '|' || COALESCE('V' || TO_CHAR(CAST("booked" AS TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS.US'), 'N') || '|' || COALESCE('V' || TO_CHAR(("created_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 'N') || '|' || COALESCE('V' || SUBSTR(TO_CHAR((("updated_at" AT TIME ZONE 'Asia/Singapore') AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 1, 23), 'N')), 18), 16) AS h FROM analytics.loans WHERE (status <> 'TEST')) t WHERE ((((kh) / (1048576))) % (10000)) < 500 AND ((kh) % (64)) IN (3, 9) GROUP BY 1

-- hash_fetch
SELECT c0, c1, c2, c3, c4, c5, c6, c7, c8, c9, c10 FROM (SELECT CAST("loan_id" AS VARCHAR(65535)) AS c0, CAST(CAST("amount" AS DECIMAL(38, 2)) AS VARCHAR(65535)) AS c1, CAST(CAST(CAST("rate" AS DOUBLE PRECISION) AS DECIMAL(38, 6)) AS VARCHAR(65535)) AS c2, NULLIF(RTRIM(CAST("status" AS VARCHAR(65535))), '') AS c3, LOWER(CAST("ref" AS VARCHAR(65535))) AS c4, CASE WHEN "active" THEN 'true' WHEN NOT "active" THEN 'false' END AS c5, CASE WHEN "flag" THEN '1' WHEN NOT "flag" THEN '0' END AS c6, TO_CHAR("opened", 'YYYY-MM-DD') AS c7, TO_CHAR(CAST("booked" AS TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS.US') AS c8, TO_CHAR(("created_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US') AS c9, SUBSTR(TO_CHAR((("updated_at" AT TIME ZONE 'Asia/Singapore') AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 1, 23) AS c10, STRTOL(SUBSTRING(MD5(COALESCE('V' || CAST("loan_id" AS VARCHAR(65535)), 'N')), 18), 16) AS kh FROM analytics.loans WHERE (status <> 'TEST')) t WHERE ((kh) % (2048)) IN (67, 131)

-- join_diff
SELECT l.c0, l.c1, l.c2, l.c3, l.c4, l.c5, l.c6, l.c7, l.c8, l.c9, l.c10, r.c0, r.c1, r.c2, r.c3, r.c4, r.c5, r.c6, r.c7, r.c8, r.c9, r.c10, l.j0, r.j0 FROM (SELECT CAST("loan_id" AS VARCHAR(65535)) AS c0, CAST(CAST("amount" AS DECIMAL(38, 2)) AS VARCHAR(65535)) AS c1, CAST(CAST(CAST("rate" AS DOUBLE PRECISION) AS DECIMAL(38, 6)) AS VARCHAR(65535)) AS c2, NULLIF(RTRIM(CAST("status" AS VARCHAR(65535))), '') AS c3, LOWER(CAST("ref" AS VARCHAR(65535))) AS c4, CASE WHEN "active" THEN 'true' WHEN NOT "active" THEN 'false' END AS c5, CASE WHEN "flag" THEN '1' WHEN NOT "flag" THEN '0' END AS c6, TO_CHAR("opened", 'YYYY-MM-DD') AS c7, TO_CHAR(CAST("booked" AS TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS.US') AS c8, TO_CHAR(("created_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US') AS c9, SUBSTR(TO_CHAR((("updated_at" AT TIME ZONE 'Asia/Singapore') AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 1, 23) AS c10, COALESCE('V' || CAST("loan_id" AS VARCHAR(65535)), 'N') AS j0 FROM analytics.loans WHERE (status <> 'TEST')) l FULL OUTER JOIN (SELECT CAST("loan_id" AS VARCHAR(65535)) AS c0, CAST(CAST("amount" AS DECIMAL(38, 2)) AS VARCHAR(65535)) AS c1, CAST(CAST(CAST("rate" AS DOUBLE PRECISION) AS DECIMAL(38, 6)) AS VARCHAR(65535)) AS c2, NULLIF(RTRIM(CAST("status" AS VARCHAR(65535))), '') AS c3, LOWER(CAST("ref" AS VARCHAR(65535))) AS c4, CASE WHEN "active" THEN 'true' WHEN NOT "active" THEN 'false' END AS c5, CASE WHEN "flag" THEN '1' WHEN NOT "flag" THEN '0' END AS c6, TO_CHAR("opened", 'YYYY-MM-DD') AS c7, TO_CHAR(CAST("booked" AS TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS.US') AS c8, TO_CHAR(("created_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US') AS c9, SUBSTR(TO_CHAR((("updated_at" AT TIME ZONE 'Asia/Singapore') AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS.US'), 1, 23) AS c10, COALESCE('V' || CAST("loan_id" AS VARCHAR(65535)), 'N') AS j0 FROM analytics.loans WHERE (status <> 'TEST')) r ON l.j0 = r.j0 WHERE l.j0 IS NULL OR r.j0 IS NULL OR COALESCE('V' || l.c1, 'N') <> COALESCE('V' || r.c1, 'N') OR COALESCE('V' || l.c2, 'N') <> COALESCE('V' || r.c2, 'N') OR COALESCE('V' || l.c3, 'N') <> COALESCE('V' || r.c3, 'N') OR COALESCE('V' || l.c4, 'N') <> COALESCE('V' || r.c4, 'N') OR COALESCE('V' || l.c5, 'N') <> COALESCE('V' || r.c5, 'N') OR COALESCE('V' || l.c6, 'N') <> COALESCE('V' || r.c6, 'N') OR COALESCE('V' || l.c7, 'N') <> COALESCE('V' || r.c7, 'N') OR COALESCE('V' || l.c8, 'N') <> COALESCE('V' || r.c8, 'N') OR COALESCE('V' || l.c9, 'N') <> COALESCE('V' || r.c9, 'N') OR COALESCE('V' || l.c10, 'N') <> COALESCE('V' || r.c10, 'N')

-- columns
SELECT column_name, data_type, numeric_precision, numeric_scale, is_nullable FROM information_schema.columns WHERE table_name = 'loans' AND table_schema = 'analytics' ORDER BY ordinal_position

